input.command:
cd /scr/wurgaft/auto-psych/agent_trees/8a52ff3d6e8e6ef7/repo/_runs/cell_1/experiment3/model_loop/iter_3/critique/scratch; cat > sim.py << 'EOF'
import pandas as pd, numpy as np
df=pd.read_pickle("df.pkl"); rng=np.random.default_rng(0)
ex=df.number_set.str.split(",").apply(lambda l:[int(x) for x in l]); t=df.target
def isprime(n): return n>1 and all(n%a for a in range(2,int(n**.5)+1))
first=ex.str[0]
stats={
 "setsd": lambda r: df[~df.isex&(df.n>=2)].assign(r=r[~df.isex&(df.n>=2)]).groupby("number_set").r.mean().std(),
 "single_prime": lambda r: r[(df.n==1)&~df.isex&first.apply(isprime)].mean(),
 "single_mult5": lambda r: r[(df.n==1)&~df.isex&(first%5==0)].mean(),
 "single_prime_minus_m5": lambda r: r[(df.n==1)&~df.isex&first.apply(isprime)].mean()-r[(df.n==1)&~df.isex&(first%5==0)].mean(),
 "single_opp": lambda r: r[(df.n==1)&(df.tpar_match==0)].mean(),
 "ab4": lambda r: r[~df.isex&(df.n==4)&(df.side=="above")].mean()-r[~df.isex&(df.n==4)&(df.side=="below")].mean(),
 "ex_target_2": lambda r: r[df.isex&(df.n==2)].mean(),
}
obs={k:f(df.rating.values) for k,f in stats.items()}
P=df.p.values
sims={k:[] for k in stats}
for i in range(300):
    y=(rng.random(len(P))<P).astype(int)
    for k,f in stats.items(): sims[k].append(f(y))
for k in stats:
    a=np.array(sims[k]); print(k, round(obs[k],3), round(a.mean(),3), round((obs[k]-a.mean())/a.std(),2))
EOF
python3 sim.py

